// Il sito di vendita nella lingua del telefono (inglese, spagnolo, tedesco, francese; altrimenti italiano).
// Si traduce dopo che la pagina è disegnata: ogni testo italiano noto viene sostituito. ?lang=en per forzare.
// Ordine delle traduzioni: [en, es, de, fr]
const L = ["en", "es", "de", "fr"];
export function lingua() {
  const forza = new URLSearchParams(location.search).get("lang") ?? new URLSearchParams(location.hash.split("?")[1] ?? "").get("lang");
  if (forza) { try { localStorage.setItem("ancora_lingua", forza); } catch { /* niente */ } }
  let l = forza; try { l ??= localStorage.getItem("ancora_lingua"); } catch { /* niente */ }
  l ??= (navigator.languages?.[0] ?? navigator.language ?? "it");
  l = String(l).slice(0, 2).toLowerCase();
  return L.includes(l) ? l : "it";
}

