const NORM = (t) => t.replace(/\s+/g, " ").trim();
const IDX = { en: 0, es: 1, de: 2, fr: 3 };

/** Traduce i testi italiani noti dentro radice (testi e placeholder/aria-label). */
export function traduci(radice = document.body, l = lingua()) {
  if (l === "it") return;
  const i = IDX[l];
  document.documentElement.lang = l;
  const w = document.createTreeWalker(radice, NodeFilter.SHOW_TEXT);
  const nodi = []; while (w.nextNode()) nodi.push(w.currentNode);
  for (const n of nodi) {
    const t = NORM(n.nodeValue); if (!t) continue;
    const v = D[t]?.[i]; if (!v) continue;
    const prima = n.nodeValue.match(/^\s*/)[0], dopo = n.nodeValue.match(/\s*$/)[0];
    n.nodeValue = prima + v + dopo;
  }
  radice.querySelectorAll?.("[placeholder],[aria-label]").forEach((e) => {
    for (const a of ["placeholder", "aria-label"]) { const v = e.getAttribute(a); const x = v && D[NORM(v)]?.[i]; if (x) e.setAttribute(a, x); }
  });
}

/** Traduce e continua a tradurre ciò che cambia (pulsanti, modulo, banner cookie). */
export function traduciSempre(radice) {
  const l = lingua(); if (l === "it") return;
  traduci(radice, l);
  traduci(document.getElementById("banner-cookie") ?? document.createElement("div"), l);
  const os = new MutationObserver(() => { os.disconnect(); traduci(radice, l); const bc = document.getElementById("banner-cookie"); if (bc) traduci(bc, l); osserva(); });
  const osserva = () => { os.observe(radice, { childList: true, subtree: true, characterData: true }); os.observe(document.body, { childList: true }); };
  osserva();
  addEventListener("hashchange", () => os.disconnect(), { once: true });
}
